{"file_path":"src/address.js","content":"/**
 * Cell addresses. A column is one or two letters (`A`..`Z`, then `AA`..`ZZ`)
 * and a row is one to three digits naming a row of at least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Turn the letters of a column into its zero based index. */
export function columnIndex(letters) {
  let index = 0
  for (const ch of letters.toUpperCase()) index = index * 26 + (ch.charCodeAt(0) - 64)
  return index - 1
}

/** Turn a zero based column index back into its letters. */
export function columnName(index) {
  let name = ''
  let n = index + 1
  while (n > 0) {
    const rem = (n - 1) % 26
    name = String.fromCharCode(65 + rem) + name
    n = Math.floor((n - 1) / 26)
  }
  return name
}

/**
 * Read a word as an address. Returns null when the word names no cell inside
 * the addressable range.
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { name: word.toUpperCase(), col: columnIndex(m[1]), row }
}

/** Order two addresses by column and then by row. */
export function compareAddresses(a, b) {
  return a.col - b.col || a.row - b.row
}

/** Every cell a range covers, from whichever corner it was written. */
export function expandRange(a, b) {
  const c0 = Math.min(a.col, b.col)
  const c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row)
  const r1 = Math.max(a.row, b.row)
  const cells = []
  for (let c = c0; c <= c1; c++) {
    const letters = columnName(c)
    for (let r = r0; r <= r1; r++) cells.push({ name: letters + r, col: c, row: r })
  }
  return cells
}
"}

