{"file_path":"src/sheet.js","content":"/**
 * Reading a sheet: one cell per line, an address and then the content the rest
 * of the line holds verbatim.
 */

import { parseAddress, compareAddresses } from './address.js'

export class SheetError extends Error {}

/**
 * Read the text of a sheet into cells ordered by column and then by row.
 * Throws a SheetError on the first bad or repeated address.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const byName = new Map()
  const cells = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const word = line.slice(0, end)
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) {
      rest++
      break
    }
    const content = line.slice(rest)

    const address = parseAddress(word)
    if (!address) throw new SheetError(`line ${lineNo}: invalid cell address ${word}`)
    if (byName.has(address.name)) {
      throw new SheetError(`line ${lineNo}: cell ${address.name} is declared twice`)
    }
    const cell = { name: address.name, col: address.col, row: address.row, content }
    byName.set(address.name, cell)
    cells.push(cell)
  }

  cells.sort(compareAddresses)
  return { cells, byName }
}
"}

