{"file_path":"src/formula.js","content":"/**
 * The formula language: turning the body of a formula into a syntax tree.
 * Anything the grammar does not accept leaves the cell in error.
 */

const OPERATORS = ['<>', '<=', '>=', '<', '>', '=', '+', '-', '*', '/', '^', '(', ')', ',', ':']

/** Split a formula body into tokens, or return null when a character fits none. */
export function tokenize(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const ch = source[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < source.length && source[j] >= '0' && source[j] <= '9') j++
      if (source[j] === '.' && source[j + 1] >= '0' && source[j + 1] <= '9') {
        j++
        while (j < source.length && source[j] >= '0' && source[j] <= '9') j++
      }
      tokens.push({ kind: 'number', text: source.slice(i, j) })
      i = j
      continue
    }
    if (isLetter(ch)) {
      let j = i
      while (j < source.length && isLetter(source[j])) j++
      while (j < source.length && source[j] >= '0' && source[j] <= '9') j++
      tokens.push({ kind: 'word', text: source.slice(i, j) })
      i = j
      continue
    }
    const op = OPERATORS.find((candidate) => source.startsWith(candidate, i))
    if (!op) return null
    tokens.push({ kind: op, text: op })
    i += op.length
    continue
  }
  return tokens
}

function isLetter(ch) {
  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')
}

const COMPARISONS = new Set(['=', '<>', '<', '<=', '>', '>='])

/**
 * Parse a formula body. Returns the syntax tree, or null when the grammar does
 * not accept the body.
 */
export function parseFormula(source) {
  const tokens = tokenize(source)
  if (!tokens) return null
  let pos = 0

  const peek = () => (pos < tokens.length ? tokens[pos] : null)
  const at = (kind) => pos < tokens.length && tokens[pos].kind === kind

  function fail() {
    throw new SyntaxFailure()
  }

  function expect(kind) {
    if (!at(kind)) fail()
    return tokens[pos++]
  }

  function comparison() {
    let left = additive()
    while (peek() && COMPARISONS.has(peek().kind)) {
      const op = tokens[pos++].kind
      left = { kind: 'binary', op, left, right: additive() }
    }
    return left
  }

  function additive() {
    let left = multiplicative()
    while (at('+') || at('-')) {
      const op = tokens[pos++].kind
      left = { kind: 'binary', op, left, right: multiplicative() }
    }
    return left
  }

  function multiplicative() {
    let left = power()
    while (at('*') || at('/')) {
      const op = tokens[pos++].kind
      left = { kind: 'binary', op, left, right: power() }
    }
    return left
  }

  function power() {
    const base = unary()
    if (at('^')) {
      pos++
      return { kind: 'binary', op: '^', left: base, right: power() }
    }
    return base
  }

  function unary() {
    if (at('-') || at('+')) {
      const op = tokens[pos++].kind
      return { kind: 'unary', op, operand: unary() }
    }
    return primary()
  }

  function primary() {
    const token = peek()
    if (!token) fail()
    if (token.kind === 'number') {
      pos++
      return { kind: 'number', value: Number(token.text) }
    }
    if (token.kind === '(') {
      pos++
      const inner = comparison()
      expect(')')
      return { kind: 'group', operand: inner }
    }
    if (token.kind === 'word') {
      pos++
      if (at('(')) {
        pos++
        const args = []
        if (!at(')')) {
          args.push(comparison())
          while (at(',')) {
            pos++
            args.push(comparison())
          }
        }
        expect(')')
        return { kind: 'call', name: token.text, args }
      }
      if (at(':')) {
        pos++
        const end = expect('word')
        return { kind: 'range', from: token.text, to: end.text }
      }
      return { kind: 'word', name: token.text }
    }
    return fail()
  }

  try {
    const tree = comparison()
    if (pos !== tokens.length) return null
    return tree
  } catch (error) {
    if (error instanceof SyntaxFailure) return null
    throw error
  }
}

class SyntaxFailure extends Error {}

/**
 * Whether every range in the tree sits directly as a function argument. A range
 * anywhere else is accepted by the grammar but leaves the cell in error.
 */
export function rangesWellPlaced(node, allowed = false) {
  if (node.kind === 'range') return allowed
  switch (node.kind) {
    case 'number':
    case 'word':
      return true
    case 'group':
      return rangesWellPlaced(node.operand, false)
    case 'unary':
      return rangesWellPlaced(node.operand, false)
    case 'binary':
      return rangesWellPlaced(node.left, false) && rangesWellPlaced(node.right, false)
    case 'call':
      return node.args.every((arg) => rangesWellPlaced(arg, true))
    default:
      return true
  }
}
"}

