{"file_path":"src/values.js","content":"/** Values: a number, a text, a boolean, or an error. */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const num = (value) => ({ kind: 'number', value })
export const text = (value) => ({ kind: 'text', value })
export const bool = (value) => ({ kind: 'boolean', value })
export const err = (token) => ({ kind: 'error', token })

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME = err('#NAME?')
export const ERR = err('#ERR!')

export const isError = (value) => value.kind === 'error'

/** Read a value in an arithmetic position, or return the error that stops it. */
export function asNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return num(value.value ? 1 : 0)
  if (value.kind === 'error') return value
  return VALUE
}

/** A finite number, or the error an infinite or undefined result becomes. */
export function finite(value) {
  return Number.isFinite(value) ? num(value) : DIV0
}

function compareText(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i++) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length === right.length ? 0 : left.length < right.length ? -1 : 1
}

const RANK = { number: 0, text: 1, boolean: 2 }

/** Order two values: numbers below texts below booleans. */
export function compareValues(a, b) {
  if (RANK[a.kind] !== RANK[b.kind]) return RANK[a.kind] < RANK[b.kind] ? -1 : 1
  if (a.kind === 'number') return a.value === b.value ? 0 : a.value < b.value ? -1 : 1
  if (a.kind === 'text') return compareText(a.value, b.value)
  const x = a.value ? 1 : 0
  const y = b.value ? 1 : 0
  return x === y ? 0 : x < y ? -1 : 1
}

/** Print a value the way the `values` mode reports it. */
export function formatValue(value) {
  switch (value.kind) {
    case 'number':
      return formatNumber(value.value)
    case 'text':
      return value.value
    case 'boolean':
      return value.value ? 'TRUE' : 'FALSE'
    default:
      return value.token
  }
}

function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

const LITERAL_NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

/** Read the content of a cell that is not a formula. */
export function literalValue(content) {
  if (content === '') return num(0)
  if (LITERAL_NUMBER.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}
"}

