      case 'word':
        return this.evaluateWord(node.name)
      case 'range':
        return ERR
      case 'unary':
        return this.evaluateUnary(node)
      case 'binary':
        return this.evaluateBinary(node)
      case 'call':
        return this.evaluateCall(node)
      default:
        return ERR
    }
  }

  evaluateWord(name) {
    const upper = name.toUpperCase()
    if (upper === 'TRUE') return bool(true)
    if (upper === 'FALSE') return bool(false)
    const address = parseAddress(name)
    if (!address) return REF
    return this.valueOf(address.name)
  }

  evaluateUnary(node) {
    const operand = asNumber(this.evaluate(node.operand))
    if (isError(operand)) return operand
    return finite(node.op === '-' ? -operand.value : operand.value)
  }

  evaluateBinary(node) {
    const left = this.evaluate(node.left)
    const right = this.evaluate(node.right)
    if (node.op === '=' || node.op === '<>' || node.op === '<' || node.op === '<=' || node.op === '>' || node.op === '>=') {
      if (isError(left)) return left
      if (isError(right)) return right
      const order = compareValues(left, right)
      switch (node.op) {
        case '=':
          return bool(order === 0)
        case '<>':
          return bool(order !== 0)
        case '<':
          return bool(order < 0)
        case '<=':
          return bool(order <= 0)
        case '>':
          return bool(order > 0)
        default:
          return bool(order >= 0)
      }
    }
    const a = asNumber(left)
    if (isError(a)) return a
    const b = asNumber(right)
    if (isError(b)) return b
    switch (node.op) {
      case '+':
        return finite(a.value + b.value)
      case '-':
        return finite(a.value - b.value)
      case '*':
        return finite(a.value * b.value)
      case '/':
        return b.value === 0 ? DIV0 : finite(a.value / b.value)
      default:
        return finite(a.value ** b.value)
    }
  }

  /** Every value an argument stands for, a range contributing all of its cells. */
  argumentValues(node) {
    if (node.kind !== 'range') return [this.evaluate(node)]
    const from = parseAddress(node.from)
    const to = parseAddress(node.to)
    if (!from || !to) return [REF]
    return expandRange(from, to).map((address) => this.valueOf(address.name))
  }

  evaluateCall(node) {
    const name = node.name.toUpperCase()
    if (!(name in ARITY)) return NAME
    const arity = ARITY[name]
    if (arity === null ? node.args.length < 1 : node.args.length !== arity) return ERR
    if (name === 'IF') return this.evaluateIf(node)

    const values = []
    for (const arg of node.args) values.push(...this.argumentValues(arg))
    const failure = values.find(isError)
    if (failure) return failure
    if (name === 'COUNT') return num(values.filter((value) => value.kind === 'number').length)
    if (name === 'ABS' && values.length !== 1) return ERR

    const numbers = []
    for (const value of values) {
      const converted = asNumber(value)
      if (isError(converted)) return converted
      numbers.push(converted.value)
    }
    switch (name) {
      case 'ABS':
        return finite(Math.abs(numbers[0]))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
      default:
        return finite(numbers.reduce((a, b) => a + b, 0))
    }
  }

  evaluateIf(node) {
    const condition = this.argumentValues(node.args[0])
    const failure = condition.find(isError)
    if (failure) return failure
    if (condition.length !== 1) return ERR
    const test = condition[0]
    let taken
    if (test.kind === 'boolean') taken = test.value
    else if (test.kind === 'number') taken = test.value !== 0
    else return VALUE
    const branch = this.argumentValues(node.args[taken ? 1 : 2])
    const branchFailure = branch.find(isError)
    if (branchFailure) return branchFailure
    if (branch.length !== 1) return ERR
    return branch[0]
  }
}

function collect(node, found) {
  switch (node.kind) {
    case 'word': {
      const upper = node.name.toUpperCase()
      if (upper === 'TRUE' || upper === 'FALSE') return
      const address = parseAddress(node.name)
      if (address) found.set(address.name, address)
      return
    }
    case 'range': {
      const from = parseAddress(node.from)
      const to = parseAddress(node.to)
      if (!from || !to) return
      for (const address of expandRange(from, to)) found.set(address.name, address)
      return
    }
    case 'group':
    case 'unary':
      collect(node.operand, found)
      return
    case 'binary':
      collect(node.left, found)
      collect(node.right, found)
      return
    case 'call':
      for (const arg of node.args) collect(arg, found)
      return
    default:
  }
}

export { err }
"}

