{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Sheet } from './evaluate.js'
import { formatValue } from './values.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function main(argv) {
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'values' && mode !== 'deps') {
    fail('usage: cli.js values|deps')
    return
  }

  let parsed
  try {
    parsed = parseSheet(readStdin())
  } catch (error) {
    if (error instanceof SheetError) {
      fail(error.message)
      return
    }
    throw error
  }

  const sheet = new Sheet(parsed)
  const lines = []
  for (const cell of parsed.cells) {
    if (mode === 'values') {
      lines.push(`${cell.name}=${formatValue(sheet.valueOf(cell.name))}\n`)
    } else {
      const deps = sheet.dependencies(cell)
      lines.push(`${cell.name}:${deps.map((address) => ` ${address.name}`).join('')}\n`)
    }
  }
  process.stdout.write(lines.join(''))
}

main(process.argv.slice(2))
"}

